from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    # The palette is the repeated three-row bar, read left to right.
    palette = None
    for r in range(h - 2):
        if grid[r] == grid[r + 1] == grid[r + 2]:
            vals = [v for v in grid[r] if v != 0]
            if len(vals) >= 2:
                palette = vals
                break
    if palette is None:
        raise ValueError('palette bar not found')

    # Locate the connected color-1 pattern, which is the template to replicate.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 1 and (r, c) not in seen:
                q = deque([(r, c)])
                seen.add((r, c))
                comp = []
                while q:
                    y, x = q.popleft()
                    comp.append((y, x))
                    for dy in (-1,0,1):
                        for dx in (-1,0,1):
                            if dy == dx == 0:
                                continue
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 1 and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
                components.append(comp)
    if not components:
        raise ValueError('template not found')
    comp = max(components, key=len)
    top = min(y for y, x in comp); left = min(x for y, x in comp)
    bottom = max(y for y, x in comp); right = max(x for y, x in comp)
    mask = {(y-top, x-left) for y, x in comp}
    bh, bw = bottom-top+1, right-left+1
    color_index = palette.index(1)
    out = [[0]*w for _ in range(h)]
    first_top = top - color_index * bh
    for i, color in enumerate(palette):
        y0 = first_top + i * bh
        for dy, dx in mask:
            y, x = y0+dy, left+dx
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = color
    return out

